public static void main(Args args)
{
    METRebateExcludeForPaymentController controller;
    controller = new METRebateExcludeForPaymentController();
    
    controller.parmArgs(args);
    controller.initContract();
    controller.startOperation();
}

public static METRebateExcludeForPaymentController construct()
{
    return new METRebateExcludeForPaymentController();
}

private void initContract()
{
    DictMethod dictMethod = new SysDictMethod(UtilElementType::ClassInstanceMethod, className2Id(this.parmClassName()), this.parmMethodName());
    str dataContractKey = dictMethod.parameterName(1);

    METRebateExcludeForPaymentContract contract = this.getDataContractObject(dataContractKey) as METRebateExcludeForPaymentContract;
    contract.parmTAMRebateDeal(this.parmArgs().record());
}
